1:package com.example.home_garden_system.garden
2:
3:import androidx.lifecycle.ViewModel
4:import androidx.lifecycle.viewModelScope
5:import kotlinx.coroutines.CancellationException
6:import kotlinx.coroutines.CoroutineScope
7:import kotlinx.coroutines.delay
8:import kotlinx.coroutines.flow.MutableStateFlow
9:import kotlinx.coroutines.flow.asStateFlow
10:import kotlinx.coroutines.flow.update
11:import kotlinx.coroutines.launch
12:import java.util.UUID
13:
14:data class GardenUiState(
15:    val repository: RepositoryState = RepositoryState(),
16:    val demo: Boolean = false,
17:    val now: Long = 0,
18:    val busy: Boolean = false,
19:    val message: String? = null,
20:    val pending: PendingWatering? = null,
21:) {
22:    val online: Boolean get() = repository.garden.isOnline(now, repository.connected)
23:    val canWater: Boolean get() = !busy && pending == null &&
24:        repository.garden.wateringBlockedReason(now, repository.connected) == null
25:    val canConfigure: Boolean get() = !busy && pending == null && repository.connected &&
26:        repository.garden.settings != null && !repository.garden.manualWater
27:}
28:
29:class GardenViewModel(
30:    private val repository: GardenRepository,
31:    scopeOverride: CoroutineScope? = null,
32:    private val clock: () -> Long = { System.currentTimeMillis() / 1000 },
33:) : ViewModel() {
34:    private val workScope = scopeOverride ?: viewModelScope
35:    private val mutableUi = MutableStateFlow(GardenUiState(demo = repository.isDemo))
36:    val ui = mutableUi.asStateFlow()
37:
38:    init {
39:        workScope.launch {
40:            repository.state.collect { state ->
41:                mutableUi.update { it.copy(repository = state) }
42:                tick()
43:            }
44:        }
45:        workScope.launch { while (true) { tick(); delay(1000) } }
46:    }
47:
48:    private fun tick() {
49:        mutableUi.update { current ->
50:            val now = clock() + current.repository.serverOffsetMs / 1000
51:            val pending = current.pending
52:            val status = pending?.status(current.repository.garden.acknowledgedRequestId, now)
53:            when (status) {
54:                RequestStatus.ACCEPTED -> current.copy(now = now, pending = null,
55:                    message = "Perintah diterima perangkat. Pantau status pompa.")
56:                RequestStatus.EXPIRED -> current.copy(now = now, pending = null,
57:                    message = "Perintah kedaluwarsa tanpa konfirmasi. Periksa perangkat sebelum mencoba lagi.")
58:                else -> current.copy(now = now)
59:            }
60:        }
61:    }
62:
63:    fun login(email: String, password: String) {
64:        if (!repository.isDemo && (email.isBlank() || password.isBlank())) {
65:            mutableUi.update { it.copy(message = "Isi email dan kata sandi terlebih dahulu.") }
66:            return
67:        }
68:        action { repository.login(email.trim(), password) }
69:    }
70:
71:    fun logout() {
72:        repository.logout()
73:        mutableUi.value = GardenUiState(demo = repository.isDemo)
74:    }
75:
76:    fun saveSettings(settings: ControlSettings) {
77:        settings.validationError()?.let { error ->
78:            mutableUi.update { it.copy(message = error) }; return
79:        }
80:        if (!ui.value.canConfigure) return
81:        action {
82:            repository.saveSettings(settings)
83:            mutableUi.update { it.copy(message = "Pengaturan berhasil disimpan.") }
84:        }
85:    }
86:
87:    fun water() {
88:        if (!ui.value.canWater) return
89:        val request = PendingWatering(UUID.randomUUID().toString(), ui.value.now + 10)
90:        mutableUi.update { it.copy(pending = request, message = null) }
91:        action {
92:            try { repository.water(request) }
93:            catch (error: Exception) {
94:                mutableUi.update { it.copy(pending = null) }
95:                throw error
96:            }
97:        }
98:    }
99:
100:    fun dismissMessage() = mutableUi.update { it.copy(message = null) }
101:
102:    private fun action(block: suspend () -> Unit) {
103:        if (mutableUi.value.busy) return
104:        mutableUi.update { it.copy(busy = true, message = null) }
105:        workScope.launch {
106:            try { block() }
107:            catch (error: CancellationException) { throw error }
108:            catch (error: Exception) {
109:                mutableUi.update { it.copy(message = (error as? GardenException)?.message
110:                    ?: "Terjadi kesalahan. Periksa koneksi dan coba lagi.") }
111:            } finally { mutableUi.update { it.copy(busy = false) } }
112:        }
113:    }
114:
115:    override fun onCleared() { repository.close() }
116:}

