1:package com.example.home_garden_system.garden
2:
3:import kotlinx.coroutines.CoroutineScope
4:import kotlinx.coroutines.Dispatchers
5:import kotlinx.coroutines.SupervisorJob
6:import kotlinx.coroutines.cancel
7:import kotlinx.coroutines.delay
8:import kotlinx.coroutines.flow.MutableStateFlow
9:import kotlinx.coroutines.flow.asStateFlow
10:import kotlinx.coroutines.flow.update
11:import kotlinx.coroutines.launch
12:
13:/** A visibly simulated, in-memory garden. Never used by the live flavor. */
14:class DemoGardenRepository : GardenRepository {
15:    override val isDemo = true
16:    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
17:    private val mutableState = MutableStateFlow(RepositoryState())
18:    override val state = mutableState.asStateFlow()
19:    private var pumpStarted = 0L
20:    private var stoppedAt = 0L
21:    private var ticks = 0
22:
23:    init {
24:        scope.launch {
25:            while (true) {
26:                delay(1000)
27:                if (state.value.email != null) simulate()
28:            }
29:        }
30:    }
31:
32:    override suspend fun login(email: String, password: String) {
33:        val now = System.currentTimeMillis() / 1000
34:        pumpStarted = 0
35:        stoppedAt = 0
36:        ticks = 0
37:        mutableState.value = RepositoryState(email = "Sahabat Hijau", connected = true,
38:            garden = GardenSnapshot(sensors = SensorReadings(42, 2140, 28.5, 67.0, 920.0, now),
39:                settings = ControlSettings(), pumpRunning = false, lastSeen = now, deviceOnline = true))
40:    }
41:
42:    override fun logout() { mutableState.value = RepositoryState() }
43:
44:    override suspend fun saveSettings(settings: ControlSettings) {
45:        settings.validationError()?.let { throw GardenException(it) }
46:        if (state.value.email == null) throw GardenException("Masuk terlebih dahulu.")
47:        val garden = state.value.garden
48:        val changingMode = garden.settings?.mode != settings.mode
49:        if (changingMode && garden.pumpRunning == true) stoppedAt = System.currentTimeMillis()
50:        mutableState.update { it.copy(garden = garden.copy(settings = settings,
51:            pumpRunning = if (changingMode) false else garden.pumpRunning)) }
52:    }
53:
54:    override suspend fun water(request: PendingWatering) {
55:        val now = System.currentTimeMillis() / 1000
56:        state.value.garden.wateringBlockedReason(now, state.value.connected)?.let { throw GardenException(it) }
57:        mutableState.update { it.copy(garden = it.garden.copy(manualWater = true,
58:            requestId = request.id, requestExpiresAt = request.expiresAt)) }
59:        delay(500)
60:        if (state.value.email == null || System.currentTimeMillis() / 1000 >= request.expiresAt) return
61:        pumpStarted = System.currentTimeMillis()
62:        mutableState.update { it.copy(garden = it.garden.copy(manualWater = false,
63:            acknowledgedRequestId = request.id, pumpRunning = true)) }
64:    }
65:
66:    private fun simulate() {
67:        ticks++
68:        val now = System.currentTimeMillis()
69:        val garden = state.value.garden
70:        val settings = garden.settings ?: return
71:        var running = garden.pumpRunning == true
72:        var soil = garden.sensors.soil ?: 42
73:        if (running) soil = (soil + 2).coerceAtMost(100)
74:        else if (ticks % 5 == 0) soil = (soil - 1).coerceAtLeast(0)
75:        if (running && (now - pumpStarted >= 15000 ||
76:                    (settings.mode == WateringMode.MANUAL && now - pumpStarted >= settings.durationMs) ||
77:                    (settings.mode == WateringMode.AUTO && soil >= settings.stop))) {
78:            running = false
79:            stoppedAt = now
80:        }
81:        if (!running && settings.mode == WateringMode.AUTO && soil <= settings.start && now - stoppedAt >= 60000) {
82:            running = true
83:            pumpStarted = now
84:        }
85:        mutableState.update { it.copy(garden = garden.copy(pumpRunning = running, lastSeen = now / 1000,
86:            sensors = garden.sensors.copy(soil = soil, soilRaw = 3100 - soil * 17, updatedAt = now / 1000))) }
87:    }
88:
89:    override fun close() = scope.cancel()
90:}

