19:    override val isDemo = false
20:    private val mutableState = MutableStateFlow(RepositoryState(loading = auth.currentUser != null))
21:    override val state = mutableState.asStateFlow()
22:    private val zone = database.getReference("smart_garden/zones/zone_a")
23:    private val connection = database.getReference(".info/connected")
24:    private val offset = database.getReference(".info/serverTimeOffset")
25:    private var zoneListener: ValueEventListener? = null
26:    private var socketConnected = false
27:    private var clockReady = false
28:    private var settingsWrite = false
29:    private var latestGarden = GardenSnapshot()
30:
31:    private val connectionListener = object : ValueEventListener {
32:        override fun onDataChange(snapshot: DataSnapshot) {
33:            socketConnected = snapshot.getValue(Boolean::class.java) == true
34:            if (!socketConnected) database.purgeOutstandingWrites()
35:            mutableState.update { it.copy(connected = socketConnected && clockReady) }
36:        }
37:        override fun onCancelled(error: DatabaseError) = report(error)
38:    }
39:    private val offsetListener = object : ValueEventListener {
40:        override fun onDataChange(snapshot: DataSnapshot) {
41:            val value = snapshot.getValue(Long::class.java)
42:            clockReady = value != null
43:            mutableState.update { it.copy(serverOffsetMs = value ?: 0, connected = socketConnected && clockReady) }
44:        }
45:        override fun onCancelled(error: DatabaseError) = report(error)
46:    }
47:    private val authListener = FirebaseAuth.AuthStateListener {
48:        zoneListener?.let(zone::removeEventListener)
49:        zoneListener = null
50:        latestGarden = GardenSnapshot()
51:        if (it.currentUser == null) {
52:            database.purgeOutstandingWrites()
53:            mutableState.update { previous -> RepositoryState(connected = previous.connected,
54:                serverOffsetMs = previous.serverOffsetMs) }
55:        } else {
56:            mutableState.update { previous -> previous.copy(email = it.currentUser?.email,
57:                garden = GardenSnapshot(), loading = true, error = null) }
58:            attachZone()
59:        }
60:    }
61:
62:    init {
63:        connection.addValueEventListener(connectionListener)
64:        offset.addValueEventListener(offsetListener)
65:        auth.addAuthStateListener(authListener)
66:    }
67:
68:    private fun attachZone() {
69:        val listener = object : ValueEventListener {
70:            override fun onDataChange(snapshot: DataSnapshot) {
71:                latestGarden = GardenSnapshot.fromMap(snapshot.value as? Map<*, *> ?: emptyMap<Any, Any>())
72:                mutableState.update { previous -> previous.copy(loading = false, error = null,
73:                    garden = if (settingsWrite) latestGarden.copy(settings = previous.garden.settings) else latestGarden) }
74:            }
75:            override fun onCancelled(error: DatabaseError) {
76:                latestGarden = GardenSnapshot()
77:                mutableState.update { it.copy(garden = GardenSnapshot()) }
78:                report(error)
79:            }
80:        }
81:        zoneListener = listener
82:        zone.addValueEventListener(listener)
83:    }
84:
85:    override suspend fun login(email: String, password: String) = translated {
86:        database.goOnline()
87:        withTimeout(15000) { auth.signInWithEmailAndPassword(email, password).await() }
88:        Unit
89:    }
90:
91:    override fun logout() {
92:        database.purgeOutstandingWrites()
93:        database.goOffline()
94:        auth.signOut()
95:    }
96:
97:    override suspend fun saveSettings(settings: ControlSettings) = translated {
98:        settings.validationError()?.let { throw GardenException(it) }
99:        requireConnection()
100:        if (state.value.garden.manualWater) throw GardenException("Tunggu konfirmasi penyiraman terlebih dahulu.")
101:        val previous = state.value.garden.settings
102:        settingsWrite = true
103:        try {
104:            withTimeout(8000) { zone.child("control").updateChildren(settings.toMap()).await() }
105:            mutableState.update { it.copy(garden = latestGarden.copy(settings = settings)) }
106:        } catch (error: Exception) {
107:            database.purgeOutstandingWrites()
108:            mutableState.update { it.copy(garden = it.garden.copy(settings = previous)) }
109:            throw error
110:        } finally { settingsWrite = false }
111:    }
112:
113:    override suspend fun water(request: PendingWatering) = translated {
114:        requireConnection()
115:        val now = (System.currentTimeMillis() + state.value.serverOffsetMs) / 1000
116:        state.value.garden.wateringBlockedReason(now, state.value.connected)?.let { throw GardenException(it) }
117:        if (request.expiresAt <= now || request.expiresAt > now + 10) throw GardenException("Perintah sudah kedaluwarsa.")
118:        try {
119:            withTimeout(8000) {
120:                zone.child("control").updateChildren(mapOf(
121:                    "manual_water" to true,
122:                    "request_id" to request.id,
123:                    "request_expires_at" to request.expiresAt,
124:                )).await()
125:            }
126:        } catch (error: Exception) {
127:            database.purgeOutstandingWrites()
128:            throw error
129:        }
130:    }
131:
132:    private fun requireConnection() {
133:        if (auth.currentUser == null) throw GardenException("Sesi berakhir. Silakan masuk kembali.")
134:        if (!state.value.connected) throw GardenException("Tidak terhubung. Perintah tidak dikirim.")
135:    }
136:
137:    private fun report(error: DatabaseError) {
138:        mutableState.update { it.copy(loading = false, error = if (error.code == DatabaseError.PERMISSION_DENIED)
139:            "Akses kebun ditolak. Periksa akun dan izin administrator di Firebase."
140:            else "Koneksi Firebase bermasalah. Periksa jaringan lalu masuk kembali.") }
141:    }
142:
143:    private suspend fun translated(block: suspend () -> Unit) {
144:        try { block() }
145:        catch (error: TimeoutCancellationException) { throw GardenException("Koneksi terlalu lama. Periksa jaringan lalu coba lagi.") }
146:        catch (error: CancellationException) { throw error }
147:        catch (error: GardenException) { throw error }
148:        catch (error: FirebaseNetworkException) { throw GardenException("Tidak dapat terhubung. Periksa koneksi internet.") }
149:        catch (error: FirebaseAuthException) { throw GardenException(when (error.errorCode) {
150:            "ERROR_INVALID_EMAIL" -> "Format email tidak valid."
151:            "ERROR_USER_DISABLED" -> "Akun dinonaktifkan. Hubungi administrator."
152:            "ERROR_TOO_MANY_REQUESTS" -> "Terlalu banyak percobaan. Tunggu sebentar."
153:            else -> "Email atau kata sandi salah."
154:        }) }
155:        catch (error: Exception) { throw GardenException("Perintah tidak berhasil. Periksa koneksi dan izin akun.") }
156:    }
157:
158:    override fun close() {
159:        database.purgeOutstandingWrites()
160:        zoneListener?.let(zone::removeEventListener)
161:        connection.removeEventListener(connectionListener)
162:        offset.removeEventListener(offsetListener)
163:        auth.removeAuthStateListener(authListener)
164:    }
165:}

