278:private fun lastUpdate(timestamp: Long, now: Long): String {
279:    if (timestamp <= 0) return "Belum ada data"
280:    val age = now - timestamp
281:    return when {
282:        age < 0 -> "Waktu perangkat tidak sesuai"
283:        age < 10 -> "Baru saja"
284:        age < 60 -> "$age detik lalu"
285:        else -> SimpleDateFormat("dd MMM, HH:mm", Locale.forLanguageTag("id-ID")).format(Date(timestamp * 1000))
286:    }
287:}

