183:    val settings = garden.settings
184:    Surface(shape = RoundedCornerShape(24.dp), color = Color.White) {
185:        Column(Modifier.fillMaxWidth().padding(20.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
186:            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
187:                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
188:                    Text("Penyiraman", fontSize = 20.sp, fontWeight = FontWeight.SemiBold)
189:                    Text("Air secukupnya, tumbuh sebaiknya.", fontSize = 11.sp, color = GardenMuted)
190:                }
191:                IconButton(onClick = configure, enabled = state.canConfigure,
192:                    modifier = Modifier.semantics { contentDescription = "Pengaturan penyiraman" }) {
193:                    GardenIcon(GardenSymbol.TUNE, color = if (state.canConfigure) GardenGreen else GardenMuted)
194:                }
195:            }
196:            Row(Modifier.fillMaxWidth().background(GardenBackground, RoundedCornerShape(14.dp)).padding(4.dp),
197:                horizontalArrangement = Arrangement.spacedBy(4.dp)) {
198:                WateringMode.entries.forEach { mode ->
199:                    val selected = settings?.mode == mode
200:                    Button(onClick = { settings?.let { save(it.copy(mode = mode)) } },
201:                        enabled = state.canConfigure, modifier = Modifier.weight(1f).heightIn(min = 44.dp),
202:                        shape = RoundedCornerShape(11.dp), elevation = null,
203:                        colors = ButtonDefaults.buttonColors(containerColor = if (selected) GardenGreen else Color.Transparent,
204:                            contentColor = if (selected) Color.White else GardenMuted,
205:                            disabledContainerColor = if (selected) GardenGreen.copy(alpha = .35f) else Color.Transparent)) {
