211:                else "ESP32 menyiram saat tanah mulai kering.", color = GardenMuted, fontSize = 12.sp, lineHeight = 18.sp)
212:            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
213:                SettingValue("Mulai pada", "${settings?.start ?: "—"}%", Modifier.weight(1f))
214:                SettingValue("Berhenti pada", "${settings?.stop ?: "—"}%", Modifier.weight(1f))
215:                SettingValue("Durasi manual", "${settings?.durationMs?.div(1000) ?: "—"} dtk", Modifier.weight(1f))
216:            }
217:            TextButton(onClick = configure, enabled = state.canConfigure, contentPadding = PaddingValues(0.dp)) {
218:                Text("Atur batas & durasi", fontSize = 12.sp)
219:                Spacer(Modifier.width(8.dp))
220:                GardenIcon(GardenSymbol.ARROW, Modifier.size(16.dp))
221:            }
222:            HorizontalDivider(color = GardenBackground)
223:            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
224:                GardenIcon(GardenSymbol.POWER, Modifier.size(18.dp))
225:                Text(if (!state.online) "Status pompa belum terkonfirmasi" else when (garden.pumpRunning) {
226:                    true -> "Pompa menyala"
227:                    false -> "Pompa beristirahat"
228:                    null -> "Menunggu status pompa"
229:                }, fontSize = 12.sp, fontWeight = FontWeight.Medium)
230:            }
