234:                else GardenIcon(GardenSymbol.DROP, Modifier.size(18.dp), if (state.canWater) Color.White else GardenMuted)
235:                Spacer(Modifier.width(9.dp))
236:                Text(if (state.pending != null) "Menunggu perangkat…" else "Siram sekarang", fontWeight = FontWeight.SemiBold)
237:            }
238:            Text(if (state.pending != null) "Perintah dikirim. Menunggu konfirmasi ESP32."
