240:                    ?: "Penyiraman ${settings?.durationMs?.div(1000)} detik setelah dikonfirmasi perangkat.",
241:                fontSize = 10.sp, color = GardenMuted, lineHeight = 16.sp)
242:        }
243:    }
244:}
