23:    Canvas(modifier.size(24.dp)) {
24:        val unit = size.minDimension / 24f
25:        scale(unit, unit, pivot = Offset.Zero) {
26:            val stroke = Stroke(1.7f, cap = StrokeCap.Round)
27:            when (symbol) {
28:                GardenSymbol.LEAF -> {
29:                    drawPath(Path().apply { moveTo(5f, 18f); cubicTo(-1f, 8f, 11f, 3f, 21f, 3f)
30:                        cubicTo(21f, 14f, 18f, 24f, 5f, 18f); close() }, color, style = stroke)
31:                    drawLine(color, Offset(3f, 22f), Offset(15f, 10f), 1.7f, StrokeCap.Round)
32:                    drawLine(color, Offset(10f, 15f), Offset(10f, 9f), 1.7f, StrokeCap.Round)
33:                }
34:                GardenSymbol.DROP -> drawPath(Path().apply { moveTo(12f, 2f)
35:                    cubicTo(10f, 6f, 4f, 11f, 4f, 15f); cubicTo(4f, 25f, 20f, 25f, 20f, 15f)
36:                    cubicTo(20f, 11f, 14f, 6f, 12f, 2f); close() }, color, style = stroke)
37:                GardenSymbol.SUN -> {
38:                    drawCircle(color, 4f, Offset(12f, 12f), style = stroke)
39:                    repeat(8) { index ->
40:                        val angle = index * Math.PI / 4
41:                        drawLine(color, Offset(12f + cos(angle).toFloat() * 8, 12f + sin(angle).toFloat() * 8),
42:                            Offset(12f + cos(angle).toFloat() * 10, 12f + sin(angle).toFloat() * 10), 1.7f, StrokeCap.Round)
43:                    }
44:                }
45:                GardenSymbol.THERMOMETER -> {
46:                    drawPath(Path().apply { moveTo(9f, 14f); lineTo(9f, 5f)
47:                        cubicTo(9f, 1f, 15f, 1f, 15f, 5f); lineTo(15f, 14f)
48:                        cubicTo(22f, 22f, 2f, 26f, 9f, 14f) }, color, style = stroke)
49:                    drawLine(color, Offset(12f, 8f), Offset(12f, 18f), 2f, StrokeCap.Round)
50:                    drawCircle(color, 2f, Offset(12f, 18f))
51:                    drawLine(color, Offset(18f, 6f), Offset(21f, 6f), 1.7f, StrokeCap.Round)
52:                }
53:                GardenSymbol.SIGNAL -> repeat(3) { index ->
54:                    drawLine(color, Offset(5f + index * 7f, 20f), Offset(5f + index * 7f, 14f - index * 5), 3f, StrokeCap.Round)
55:                }
56:                GardenSymbol.TUNE -> repeat(3) { index ->
57:                    val y = 5f + index * 7
58:                    drawLine(color, Offset(3f, y), Offset(21f, y), 1.7f, StrokeCap.Round)
59:                    drawCircle(GardenBackground, 2.5f, Offset(if (index == 1) 15f else 8f, y))
60:                    drawCircle(color, 2.5f, Offset(if (index == 1) 15f else 8f, y), style = stroke)
